// Turn the analyst's JSON answer into one Analyst Calls row per company on the watchlist
const { watchlist } = $('Your Settings').first().json;
const tickers = watchlist.split(',').map(t => t.trim().toUpperCase()).filter(Boolean);
const out = String($json.output ?? '');
let calls = [];
try { calls = JSON.parse(out.slice(out.indexOf('{'), out.lastIndexOf('}') + 1)).calls || []; } catch (e) {}
const num = x => (x === null || x === undefined || x === '' || !Number.isFinite(Number(x)) ? null : Number(x));
const CALLS = ['Research', 'Watch', 'Pass', 'No call'];

// Company names for the watchlist tickers, used when a call's ticker doesn't match.
// Add a name here when you add a ticker to the watchlist.
const NAMES = { NVDA: 'nvidia', AVGO: 'broadcom', AMAT: 'applied materials', SNPS: 'synopsys',
  MU: 'micron', TXN: 'texas instruments' };
const norm = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
const byTicker = ticker => calls.find(x => String(x.ticker ?? '').trim().toUpperCase() === ticker);
const byName = ticker => {
  const name = norm(NAMES[ticker]);
  if (!name) return undefined;
  return calls.find(x => !tickers.includes(String(x.ticker ?? '').trim().toUpperCase())
    && (norm(x.ticker).includes(name) || norm(x.company).includes(name)));
};

return tickers.map(ticker => {
  const c = byTicker(ticker) || byName(ticker) || {};
  return { json: { runDate: $now.toISODate(), ticker, company: c.company || ticker,
    price: num(c.price), growth: num(c.growth), exitMultiple: num(c.exitMultiple),
    annualReturn: num(c.annualReturn), call: CALLS.includes(c.call) ? c.call : 'No call',
    reason: c.reason || 'The analyst returned no call for this company.', savedBy: 'agent' } };
});

// Turn every proposed call into one brief, with a Saved column for the calls you approved
// Runs after the Save Calls branch; if nothing was ticked, Save Calls doesn't run and nothing is saved
const saved = new Set($('Save Calls').isExecuted ? $('Approved Calls').all().map(i => i.json.ticker) : []);
const rows = $('Read the Calls').all().map(i => ({ ...i.json, saved: saved.has(i.json.ticker) }))
  .sort((a, b) => (b.annualReturn ?? -9) - (a.annualReturn ?? -9));
const { hurdleRate, thesis } = $('Your Settings').first().json;

const pct = x => (x === null || x === undefined ? '—' : (x * 100).toFixed(1) + '%');
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const color = { Research: '#1a7f37', Watch: '#9a6700', Pass: '#cf222e' };
const count = c => rows.filter(r => r.call === c).length;

const td = 'style="padding:8px;border-bottom:1px solid #e5e5e5;vertical-align:top"';
const th = h => `<th style="text-align:left;padding:8px;border-bottom:2px solid #222">${h}</th>`;
const html = `<div style="font-family:Helvetica,Arial,sans-serif;max-width:1000px;margin:24px auto;padding:0 16px">
<h2 style="margin-bottom:4px">Investment Analyst Brief · ${$now.toFormat('MMMM d, yyyy')}</h2>
<p style="color:#555;margin-top:0">Thesis: ${esc(thesis)}<br>Hurdle ${pct(hurdleRate)} a year over 5 years · ${count('Research')} Research · ${count('Watch')} Watch · ${count('Pass')} Pass</p>
<table style="border-collapse:collapse;font-size:13px;width:100%"><tr>
${['Company', 'Price', 'Growth / yr', 'Exit multiple', 'Annual return', 'Call', 'Saved', 'Why'].map(th).join('')}</tr>
${rows.map(r => `<tr><td ${td}><b>${esc(r.ticker)}</b><br><small>${esc(r.company)}</small></td>
<td ${td}>${r.price ? '$' + Number(r.price).toFixed(2) : '—'}</td><td ${td}>${pct(r.growth)}</td>
<td ${td}>${r.exitMultiple ? r.exitMultiple + 'x' : '—'}</td><td ${td}><b>${pct(r.annualReturn)}</b></td>
<td ${td}><b style="color:${color[r.call] || '#555'}">${esc(r.call)}</b></td>
<td ${td}>${r.saved ? '<b style="color:#1a7f37">Yes</b>' : '<span style="color:#888">No</span>'}</td><td ${td}>${esc(r.reason)}</td></tr>`).join('')}
</table><p style="color:#888;font-size:12px">${saved.size} of ${rows.length} calls saved to the Analyst Calls table. Numbers from the latest 10-K (SEC) and today's price.</p></div>`;

return [{ json: { html } }];

// GitHub raw links label files as generic data; the PDF loader needs them labelled as PDFs
for (const item of $input.all()) {
  for (const file of Object.values(item.binary ?? {})) file.mimeType = 'application/pdf';
}
return $input.all();

// Lay out the proposed calls for review, with one 'Save these calls' checkbox per ticker
const rows = $input.all().map(i => i.json);
const pct = x => (x === null || x === undefined ? '—' : (x * 100).toFixed(1) + '%');
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const td = 'style="padding:6px;border-bottom:1px solid #e5e5e5;vertical-align:top;text-align:left"';
const th = h => `<th style="text-align:left;padding:6px;border-bottom:2px solid #222">${h}</th>`;
const html = `<table style="border-collapse:collapse;font-size:13px;width:100%"><tr>${['Ticker', 'Call', 'Annual return', 'Reason'].map(th).join('')}</tr>
${rows.map(r => `<tr><td ${td}><b>${esc(r.ticker)}</b></td><td ${td}>${esc(r.call)}</td><td ${td}>${pct(r.annualReturn)}</td><td ${td}>${esc(r.reason)}</td></tr>`).join('')}</table>`;

return [{ json: { fields: [
  { fieldType: 'html', elementName: 'proposedCalls', html },
  { fieldLabel: 'Save these calls', fieldName: 'Save these calls', fieldType: 'checkbox',
    fieldOptions: { values: rows.map(r => ({ option: r.ticker })) } },
] } }];

// Keep only the calls ticked on Review the Calls
let picked = $('Review the Calls').first().json['Save these calls'] ?? [];
if (typeof picked === 'string') { try { picked = JSON.parse(picked); } catch (e) { picked = picked.split(','); } }
picked = (Array.isArray(picked) ? picked : [picked]).map(t => String(t).trim().toUpperCase());

return $('Read the Calls').all()
  .filter(i => picked.includes(String(i.json.ticker).toUpperCase()))
  .map(i => ({ json: { ...i.json, savedBy: 'workflow, approved' } }));

// Turn the scheduled run's proposed calls into one brief for the approval email
const rows = $input.all().map(i => i.json)
  .sort((a, b) => (b.annualReturn ?? -9) - (a.annualReturn ?? -9));
const { hurdleRate, thesis } = $('Your Settings').first().json;

const pct = x => (x === null || x === undefined ? '—' : (x * 100).toFixed(1) + '%');
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const color = { Research: '#1a7f37', Watch: '#9a6700', Pass: '#cf222e' };
const count = c => rows.filter(r => r.call === c).length;

const td = 'style="padding:8px;border-bottom:1px solid #e5e5e5;vertical-align:top;text-align:left"';
const th = h => `<th style="text-align:left;padding:8px;border-bottom:2px solid #222">${h}</th>`;
const html = `<div style="font-family:Helvetica,Arial,sans-serif;max-width:1000px;text-align:left">
<h2 style="margin-bottom:4px">Investment Analyst Brief · ${$now.toFormat('MMMM d, yyyy')}</h2>
<p style="color:#555;margin-top:0">Thesis: ${esc(thesis)}<br>Hurdle ${pct(hurdleRate)} a year over 5 years · ${count('Research')} Research · ${count('Watch')} Watch · ${count('Pass')} Pass</p>
<table style="border-collapse:collapse;font-size:13px;width:100%"><tr>
${['Company', 'Price', 'Growth / yr', 'Exit multiple', 'Annual return', 'Call', 'Why'].map(th).join('')}</tr>
${rows.map(r => `<tr><td ${td}><b>${esc(r.ticker)}</b><br><small>${esc(r.company)}</small></td>
<td ${td}>${r.price ? '$' + Number(r.price).toFixed(2) : '—'}</td><td ${td}>${pct(r.growth)}</td>
<td ${td}>${r.exitMultiple ? r.exitMultiple + 'x' : '—'}</td><td ${td}><b>${pct(r.annualReturn)}</b></td>
<td ${td}><b style="color:${color[r.call] || '#555'}">${esc(r.call)}</b></td><td ${td}>${esc(r.reason)}</td></tr>`).join('')}
</table><p style="color:#555">Approve to save all ${rows.length} calls to the Analyst Calls table. Decline, or no reply within 24 hours, saves nothing.</p></div>`;

// The email turns line breaks into <br>, so keep the HTML on one line
return [{ json: { html: html.replace(/\n/g, '') } }];
